CREATE TABLE mss.isp_link (
	id bigint NOT NULL,
	company_id bigint,
	mc_customer_id bigint,
	account_number varchar(256),
	line_number varchar(256),
	bandwidth_down bigint,
	bandwidth_up bigint,
	sla_availability numeric,
	mtu bigint,
	router_ip_address1 bigint NOT NULL,
	comments varchar(2000),
	account_manager_id bigint,
	support_id bigint,
	event_type_id numeric(22) NOT NULL,
	product_name varchar(256),
	contract_duration bigint,
	cancellation_period bigint,
	last_review_date timestamp(0),
	monitoring_mttr bigint,
	currency_id bigint NOT NULL,
	link_installation_fee numeric,
	link_recurring_fee numeric,
	cost_comments varchar(2000),
	wan_managed smallint NOT NULL DEFAULT 0,
	isp_notification smallint NOT NULL DEFAULT 0,
	contract_end_date timestamp(0),
	router_number varchar(50),
	measured_download bigint,
	disable_osag_isp_monitoring smallint NOT NULL DEFAULT 0,
	measured_upload bigint,
	isp_link_status_type_id bigint,
	ping_ip_group_id bigint,
	maintenance_status_id bigint,
	usage_interface_id bigint,
	ipsec_internal_fragmentation smallint NOT NULL DEFAULT 0,
	router_ipv6_address_id bigint,
	wan_managed_ignore_mismatch smallint NOT NULL DEFAULT 0,
	wan_managed_ignore_reason varchar(400),
	isp_link_sourcing_type_id bigint NOT NULL,
	variable_bandwidth smallint NOT NULL DEFAULT 0,
	variable_bandwidth_identifier varchar(100),
	variable_bandwidth_down bigint,
	variable_bandwidth_up bigint,
	variable_bandwidth_qos_down bigint,
	variable_bandwidth_qos_up bigint,
	lead_time_in_weeks bigint,
	local_loop varchar(200),
	isp_link_transport_media_id bigint,
	site_id varchar(256),
	osam_id varchar(256),
	handoff_port varchar(256)
) ;
COMMENT ON COLUMN mss.isp_link.account_manager_id IS E'if set, denotes the person that is responsible for this account/line';
COMMENT ON COLUMN mss.isp_link.bandwidth_down IS E'provided downstream bandwidth [kbit/s]';
COMMENT ON COLUMN mss.isp_link.bandwidth_up IS E'provided upstream bandwidth [kbit/s]';
COMMENT ON COLUMN mss.isp_link.cancellation_period IS E'denotes the cancellation period of the contract [month]';
COMMENT ON COLUMN mss.isp_link.company_id IS E'the ISP company (usually different from the host company)';
COMMENT ON COLUMN mss.isp_link.contract_duration IS E'denotes the duration period of the contract [month]';
COMMENT ON COLUMN mss.isp_link.currency_id IS E'currency that applies to all fees for this isp link';
COMMENT ON COLUMN mss.isp_link.disable_osag_isp_monitoring IS E'Disable availability monitoring for this ISP link (affects OSAGlinkmon)';
COMMENT ON COLUMN mss.isp_link.event_type_id IS E'event type to generate when an ISP outage happens for this line';
COMMENT ON COLUMN mss.isp_link.handoff_port IS E'Provided by the ISP, lists the ports that are still available to use';
COMMENT ON COLUMN mss.isp_link.ipsec_internal_fragmentation IS E'Internal fragmentation for IPSEC tunnels';
COMMENT ON COLUMN mss.isp_link.isp_link_sourcing_type_id IS E'Denotes who is responsible for managing this ISP link';
COMMENT ON COLUMN mss.isp_link.isp_link_status_type_id IS E'Reference to the status type that describes current state of ISP link';
COMMENT ON COLUMN mss.isp_link.isp_notification IS E'boolean: denotes if notifications are sent to the ISP when ''''ISP outage'''' events occur';
COMMENT ON COLUMN mss.isp_link.last_review_date IS E'denotes the date of the last review/update of ISP contract data from this link
this is set automatically for new links, but manually for edited links';
COMMENT ON COLUMN mss.isp_link.link_installation_fee IS E'local loop cost';
COMMENT ON COLUMN mss.isp_link.maintenance_status_id IS E'Maintenance status of the host (active, inactive, maintenance, unknown) as determined by according DB job';
COMMENT ON COLUMN mss.isp_link.mc_customer_id IS E'The customer to which this isp link belongs to';
COMMENT ON COLUMN mss.isp_link.measured_download IS E'Sliding window average of download traffic on the link interface in kilobits per second';
COMMENT ON COLUMN mss.isp_link.measured_upload IS E'Sliding window average of upload traffic on the link interface in kilobits per second';
COMMENT ON COLUMN mss.isp_link.monitoring_mttr IS E'if MONITORING is set this denotes the MTTR, mean time to repair/recover [minutes]';
COMMENT ON COLUMN mss.isp_link.mtu IS E'Maximum Transmission Unit [Bytes], maximum size of packets which this link supports';
COMMENT ON COLUMN mss.isp_link.osam_id IS E'Contains the Site ID, Location ID, first or second line and version of line offer';
COMMENT ON COLUMN mss.isp_link.ping_ip_group_id IS E'Reference to the IP Group that will be used as ping targets for linkmon';
COMMENT ON COLUMN mss.isp_link.product_name IS E'how the ISP entitles this product';
COMMENT ON COLUMN mss.isp_link.router_ip_address1 IS E'IPv4 address of the router from the ISP';
COMMENT ON COLUMN mss.isp_link.router_ipv6_address_id IS E'Reference to the IPv6 address of the ISP router';
COMMENT ON COLUMN mss.isp_link.router_number IS E'Non-OSAG ID of the router used for this ISP link';
COMMENT ON COLUMN mss.isp_link.site_id IS E'Contains the Customer Site ID Registry + Location ID';
COMMENT ON COLUMN mss.isp_link.sla_availability IS E'Service Level Agreement availability of this link [%](0-100)';
COMMENT ON COLUMN mss.isp_link.support_id IS E'if set, denotes the (24h) support helpdesk of the ISP';
COMMENT ON COLUMN mss.isp_link.usage_interface_id IS E'Interface that has been used to compute the measurements for download and upload usage';
COMMENT ON COLUMN mss.isp_link.variable_bandwidth IS E'Is this ISP link enabled for variable bandwidth?';
COMMENT ON COLUMN mss.isp_link.variable_bandwidth_down IS E'Provided downstream bandwidth [kbit/s] of this variable bandwidth-enabled link';
COMMENT ON COLUMN mss.isp_link.variable_bandwidth_identifier IS E'Free-text ID that is used to map this link to the provider''''s link ID';
COMMENT ON COLUMN mss.isp_link.variable_bandwidth_qos_down IS E'Downstream QoS bandwidth [kbit/s] of this variable bandwidth-enabled link';
