CREATE TABLE nids.nids_event (
	id bigint NOT NULL,
	db_date timestamp NOT NULL DEFAULT statement_timestamp(),
	log_date timestamp NOT NULL,
	sensor_host_id bigint NOT NULL,
	sender_host_id bigint NOT NULL,
	local_event_id bigint NOT NULL,
	tt_event_id bigint,
	signature_id bigint,
	direction_id smallint NOT NULL,
	ip_source_address bigint,
	ip_source_port integer,
	ip_destination_address bigint,
	ip_destination_port integer,
	ip_protocol smallint,
	suppressed bigint NOT NULL
) ;
COMMENT ON TABLE nids.nids_event IS E'Events reported by the NIDS correlator host to be escalated as
Tickets via the MC transport layer. These are the events that were found
positives by the "escalation rules". Note that most fields of this table
are not used directly by MC, since we mostly use the database on the host
itself (HostDB). It is currently used only to map between Ticket and NIDS
Event and vice versa (LOCAL_EVENT_ID, TT_EVENT_ID). The other fields are
here for future statistical analysis.';
COMMENT ON COLUMN nids.nids_event.db_date IS E'Timestamp when this event was entered in the database.';
COMMENT ON COLUMN nids.nids_event.local_event_id IS E'Event-ID in the Host-DB (database on the correlator)';
COMMENT ON COLUMN nids.nids_event.log_date IS E'Original timestamp of the event';
COMMENT ON COLUMN nids.nids_event.sender_host_id IS E'Host-ID of the NIDS correlator that sent this event via MC transport layer';
COMMENT ON COLUMN nids.nids_event.sensor_host_id IS E'Host-ID of the sensor that reported this event to the correlator.';
COMMENT ON COLUMN nids.nids_event.suppressed IS E'Number of other events with same source and signature that were
not separately reported.';
CREATE INDEX idx_nids_event_tt_event ON nids.nids_event (tt_event_id);
CREATE UNIQUE INDEX un_event_local_event_id ON nids.nids_event (local_event_id, sender_host_id);
ALTER TABLE nids.nids_event ADD PRIMARY KEY (id);

ALTER TABLE nids.nids_event ADD CONSTRAINT nids_event_fk1 FOREIGN KEY (SENSOR_HOST_ID) REFERENCES MSS.HOST (ID);

ALTER TABLE nids.nids_event ADD CONSTRAINT nids_event_fk2 FOREIGN KEY (SENDER_HOST_ID) REFERENCES MSS.HOST (ID);

ALTER TABLE nids.nids_event ADD CONSTRAINT nids_event_fk3 FOREIGN KEY (TT_EVENT_ID) REFERENCES TT.EVENT (ID);


