CREATE TABLE tt.ticket (
	id numeric(22) NOT NULL,
	type_id numeric(22),
	status_id numeric(22) DEFAULT 1,
	subject varchar(200),
	host_id numeric(22),
	mss_service_id numeric(22),
	company_id numeric(22),
	open_date timestamp(0) DEFAULT statement_timestamp(),
	close_date timestamp(0),
	last_resolved_date timestamp(0),
	last_status_change_date timestamp(0),
	status_valid_until_date timestamp(0),
	contact_id numeric(22),
	event_notify_count numeric(22),
	event_notify_count_osag numeric(22),
	priority numeric(22) DEFAULT 1,
	worker_id numeric(22),
	customer_reference varchar(64),
	partner_reference varchar(50),
	summary_private text,
	last_summary_update timestamp(0),
	summary_public text,
	emergency smallint NOT NULL DEFAULT 0,
	always_visible smallint NOT NULL DEFAULT 0,
	handled_by_mcc smallint NOT NULL DEFAULT 1,
	escalation_status_id numeric(22) NOT NULL DEFAULT 0,
	last_escalation_date timestamp(0),
	customer_ticket_rating_id numeric(22),
	engineer_ticket_rating_id numeric(22),
	type_confirmed smallint NOT NULL DEFAULT 0,
	service_confirmed smallint NOT NULL DEFAULT 0,
	fast_resolvable smallint NOT NULL DEFAULT 0,
	last_public_event_id numeric(22),
	recoverable_status_id numeric(22),
	summary_relevant_events_count bigint NOT NULL DEFAULT 0,
	last_deferral_date timestamp(0),
	last_deferral_escalated smallint NOT NULL DEFAULT 0,
	update_timestamp timestamp NOT NULL DEFAULT statement_timestamp(),
	was_emergency smallint NOT NULL DEFAULT 0,
	steps_total bigint NOT NULL DEFAULT 0,
	steps_completed bigint NOT NULL DEFAULT 0,
	todo_relevant_events_count bigint NOT NULL DEFAULT 0,
	ux_timeout timestamp,
	ux_timeout_start timestamp NOT NULL DEFAULT statement_timestamp(),
	deleted_host_id numeric(22),
	service_component_id bigint,
	merged_into_ticket_id bigint,
	label_id bigint
) ;
COMMENT ON COLUMN tt.ticket.always_visible IS E'boolean: 1 means that this ticket is shown on top of all customer pages, 0 that it is not';
COMMENT ON COLUMN tt.ticket.customer_reference IS E'a string that is prefixed to all outgoing notifications';
COMMENT ON COLUMN tt.ticket.customer_ticket_rating_id IS E'The newest customer rating regarding the ticket handling of this ticket';
COMMENT ON COLUMN tt.ticket.emergency IS E'boolean: 1 means that this is an emergency ticket, 0 that it is not';
COMMENT ON COLUMN tt.ticket.engineer_ticket_rating_id IS E'The newest engineer rating regarding the ticket handling of this ticket';
COMMENT ON COLUMN tt.ticket.escalation_status_id IS E'escalation status of the ticket';
COMMENT ON COLUMN tt.ticket.event_notify_count IS E'counts automatic events notified in this ticket (based on the event_notification table)';
COMMENT ON COLUMN tt.ticket.event_notify_count_osag IS E'counts automatic events notified in this ticket for OSAG admins';
COMMENT ON COLUMN tt.ticket.fast_resolvable IS E'Boolean: 1 means the ticket can be resolved without adding an event';
COMMENT ON COLUMN tt.ticket.handled_by_mcc IS E'boolean: 1 means that this ticket is processed by MCC';
COMMENT ON COLUMN tt.ticket.last_deferral_date IS E'The date of the last deferral/waiting/third-party change (yes, reused).';
COMMENT ON COLUMN tt.ticket.last_deferral_escalated IS E'True means "escalate after deferral" was set when the ticket was deferred the last time.';
COMMENT ON COLUMN tt.ticket.last_escalation_date IS E'date of last escalation of the ticket';
COMMENT ON COLUMN tt.ticket.last_public_event_id IS E'The ID of the last public event of this ticket (non-history, non-notification)';
COMMENT ON COLUMN tt.ticket.merged_into_ticket_id IS E'Specifies the ticket this ticket was merged into. Requires status to be set to merged (110)';
COMMENT ON COLUMN tt.ticket.partner_reference IS E'used for partner tickets associated with this ticket';
COMMENT ON COLUMN tt.ticket.recoverable_status_id IS E'The ID of the recoverable ticket status (if any)';
COMMENT ON COLUMN tt.ticket.service_confirmed IS E'Boolean: Whether the service has been confirmed';
COMMENT ON COLUMN tt.ticket.steps_completed IS E'The number of completed steps in the Todo List of this ticket.';
COMMENT ON COLUMN tt.ticket.steps_total IS E'The total number of steps in the Todo List of this ticket.';
COMMENT ON COLUMN tt.ticket.summary_relevant_events_count IS E'Counter for the number of events since the last summary update.';
COMMENT ON COLUMN tt.ticket.todo_relevant_events_count IS E'Counter for the number of relevant events since the last todo list update.';
COMMENT ON COLUMN tt.ticket.type_confirmed IS E'Boolean: Whether the ticket type has been confirmed';
COMMENT ON COLUMN tt.ticket.update_timestamp IS E'Tells when the row was last updated. This column is updated by the trigger tt.ticket_update_trg.';
COMMENT ON COLUMN tt.ticket.ux_timeout IS E'The timeout until which MC should update the ticket with an event.';
COMMENT ON COLUMN tt.ticket.ux_timeout_start IS E'Defines the time from which the ux timeout should start.';
COMMENT ON COLUMN tt.ticket.was_emergency IS E'boolean: 1 means that this ticket had the emergency flag set at least once, 0 that it never was an emergency';
