CREATE TABLE report.channelvalue (
	id bigint NOT NULL,
	channelkey_id bigint NOT NULL,
	timestamp timestamp(0) NOT NULL,
	value varchar(2000)
) ;
COMMENT ON COLUMN report.channelvalue.channelkey_id IS E'foreign key to REPORT.CHANNELKEY.ID.';
COMMENT ON COLUMN report.channelvalue.id IS E'Unique id for this value.';
COMMENT ON COLUMN report.channelvalue.timestamp IS E'A timestamp in Oracle format that records when this value was entered.';
COMMENT ON COLUMN report.channelvalue.value IS E'The value recorded at TIMESTAMP for the tag referred to by CHANNELKEY_ID.';
CREATE INDEX channelvalue_key ON report.channelvalue (channelkey_id);
CREATE UNIQUE INDEX u_channelvalue_ck_id_ts ON report.channelvalue (channelkey_id, timestamp);
ALTER TABLE report.channelvalue ADD PRIMARY KEY (id);

ALTER TABLE report.channelvalue ADD CONSTRAINT fk_channelvalue_channelkey_id FOREIGN KEY (CHANNELKEY_ID) REFERENCES REPORT.CHANNELKEY (ID);


CREATE TABLE report.channelkey (
	id bigint NOT NULL,
	name varchar(30) NOT NULL,
	execday bigint,
	exechour bigint,
	execminute bigint,
	execinterval bigint,
	historysize bigint NOT NULL,
	lastupdated timestamp(0),
	last_value_id bigint,
	sqlquery varchar(2000) NOT NULL,
	description varchar(2000)
) ;
COMMENT ON COLUMN report.channelkey.description IS E'A description of what the tag records.';
COMMENT ON COLUMN report.channelkey.execday IS E'The day of the week on which the query in SQLQUERY should be executed. If this value is set to NULL
        the query will be executed every day. Days of the week are numbered from 0 to 6.
        0 is Monday, 6 is Sunday. If either EXECMINUTE or EXECHOUR are set to NULL, EXECDAY will be ignored.';
COMMENT ON COLUMN report.channelkey.exechour IS E'The hour at which the query in field SQLQUERY should be executed. If this value is set to NULL
        the query will be executed once every hour at the minute specified in the EXECMINUTE field.';
COMMENT ON COLUMN report.channelkey.execinterval IS E'The execution interval in minutes. This value takes precedence over EXECMINUTE,
        EXECHOUR and EXECDAY if it is set. The query in SQLQUERY will be executed,
        if SYSDATE >= LASTUPDATED + EXECINTERVAL.';
COMMENT ON COLUMN report.channelkey.execminute IS E'The minute at which the query in field SQLQUERY should be executed. If this value is set to NULL
        the query will be executed once every minute. If both values are NULL
        then EXECMINUTE takes precedence and the query shall be executed once per minute.';
COMMENT ON COLUMN report.channelkey.historysize IS E'The number of history values that are kept for this tag.';
COMMENT ON COLUMN report.channelkey.last_value_id IS E'The last value written for this key';
COMMENT ON COLUMN report.channelkey.lastupdated IS E'The last time this query has been executed.';
COMMENT ON COLUMN report.channelkey.name IS E'The name of this tag, that can be used as a parameter in "value name="tagname"';
COMMENT ON COLUMN report.channelkey.sqlquery IS E'The query that provides the value for this tag.';
CREATE UNIQUE INDEX channelkey_name ON report.channelkey (name);
CREATE INDEX idx_channelkey_lastvalue ON report.channelkey (last_value_id);
ALTER TABLE report.channelkey ADD PRIMARY KEY (id);

ALTER TABLE report.channelkey ADD CONSTRAINT fk_channelkey_last_value FOREIGN KEY (LAST_VALUE_ID) REFERENCES REPORT.CHANNELVALUE (ID);


