CREATE TABLE tt.cust_maintenance_window (
	id numeric(22) NOT NULL,
	service_window_id numeric(22) NOT NULL,
	disable_events smallint NOT NULL DEFAULT 0,
	collect_events smallint NOT NULL DEFAULT 0,
	disable_guma_escalation smallint NOT NULL DEFAULT 0,
	disable_conn_escalation smallint NOT NULL DEFAULT 0,
	disable_notification smallint NOT NULL DEFAULT 0
) ;
COMMENT ON TABLE tt.cust_maintenance_window IS E'A service window extension for type customer maintenance window.';
COMMENT ON COLUMN tt.cust_maintenance_window.collect_events IS E'If set to 1 all upcoming events not explicitly added to another ticket will get collected into this ticket until the end of the
          service window if it belongs to this host (service id) and this company. Any event that is not dropped (either because
          the specified service is not active or a service window requests event dropping (see above) for this service) will be
          collected into that  ticket with the highest id specifying a matching service window. This functionality is also implemented
          in tt.event_interface.newticket().';
COMMENT ON COLUMN tt.cust_maintenance_window.disable_conn_escalation IS E'If set to 1 any escalation to mcc, the customer and the isp caused by connection down (TT.EVENT_ACTION.ID is 2) is turned off during the service window.
          If an escalation is to be suppressed is determined in event_interface.exec_event_type_actions() by calling the function tt.event_interface.is_esc_supp_active().
          The following conditions must be met for an escalation to be suppressed:
          (1) for the host (service_id the event belongs to a currently open service window must exist, which has the disable_conn_escalation flag set to 1
          (2) the tt.event_action.id must be either 2 (connection down escalation)
          When the escalation is to be suppressed, no action will be carried out by tt.event_interface.exec_event_type_actions().';
COMMENT ON COLUMN tt.cust_maintenance_window.disable_events IS E'If set to 1 all events that belong to this node (and the ticket''''s company) and not explicitly added to a ticket (tt.event_interface.addevent())
          but with tt.event_interface.newevent() will be dropped. This causes no escalation actions or notifications to be processed for
          those events during the service window period. Of course the upcoming event must provide a host (service id), otherwise it is not possible
          to determine, if there is a service window. This function is implemented in tt.event_interface.newevent().';
COMMENT ON COLUMN tt.cust_maintenance_window.disable_guma_escalation IS E'If set to 1 any escalation to mcc, the customer and the isp caused by GUMA events is turned off during the service
          window. Only for these GUMA events escalation is suppressed: id alert, hardware error, application failure, system failure.
          If an escalation is to be suppressed is determined in event_interface.exec_event_type_actions() by calling the function tt.event_interface.is_esc_supp_active().
          The following conditions must be met for an escalation to be suppressed:
          (1) for the host (service_id the event belongs to a currently open service window must exist, which has the disable_conn_escalation flag set to 1
          (2) the tt.event_type.id must be one out of these 10002 (id alert), 10005 (hardware error), 10007 (application failure) or 10009 (system failure)
          When the escalation is to be suppressed, no action will be carried out by tt.event_interface.exec_event_type_actions().';
COMMENT ON COLUMN tt.cust_maintenance_window.disable_notification IS E'If set to 1 notification for any added event to this ticket is turned off during the service window.
          However the notification ticket bound events (resolved, manual event added and waiting) and test notifications
          will not be affected.
          Implementation is in tt.osag_notify.is_notify_suppressor_active() which checks if there is a service window open for the ticket that has
          the disable_notification flag set to 1. If so the procedure notify.event_notify() leaves out any registered notifications for this event tpye.
          It does handle the ticket specific notifications anyway.';
CREATE UNIQUE INDEX u_cust_maint_serv_window_id ON tt.cust_maintenance_window (service_window_id);
ALTER TABLE tt.cust_maintenance_window ADD PRIMARY KEY (id);

ALTER TABLE tt.cust_maintenance_window ADD CONSTRAINT cust_maintenance_window_fk1 FOREIGN KEY (SERVICE_WINDOW_ID) REFERENCES TT.SERVICE_WINDOW (ID);


CREATE TABLE tt.maintenance_window (
	id numeric(22) NOT NULL,
	service_window_id numeric(22) NOT NULL,
	disable_events smallint NOT NULL DEFAULT 0,
	collect_events smallint NOT NULL DEFAULT 0,
	disable_guma_escalation smallint NOT NULL DEFAULT 0,
	disable_conn_escalation smallint NOT NULL DEFAULT 0,
	disable_notification smallint NOT NULL DEFAULT 0
) ;
COMMENT ON TABLE tt.maintenance_window IS E'A service window extension for type maintenance window.';
COMMENT ON COLUMN tt.maintenance_window.collect_events IS E'If set to 1 all upcoming events not explicitly added to another ticket will get collected into this ticket until the end of the
          service window if it belongs to this host (service id) and this company. Any event that is not dropped (either because
          the specified service is not active or a service window requests event dropping (see above) for this service) will be
          collected into that  ticket with the highest id specifying a matching service window. This functionality is also implemented
          in tt.event_interface.newticket().';
COMMENT ON COLUMN tt.maintenance_window.disable_conn_escalation IS E'If set to 1 any escalation to mcc, the customer and the isp caused by connection down (TT.EVENT_ACTION.ID is 2) is turned off during the service window.
          If an escalation is to be suppressed is determined in event_interface.exec_event_type_actions() by calling the function tt.event_interface.is_esc_supp_active().
          The following conditions must be met for an escalation to be suppressed:
          (1) for the host (service_id the event belongs to a currently open service window must exist, which has the disable_conn_escalation flag set to 1
          (2) the tt.event_action.id must be either 2 (connection down escalation)
          When the escalation is to be suppressed, no action will be carried out by tt.event_interface.exec_event_type_actions().';
COMMENT ON COLUMN tt.maintenance_window.disable_events IS E'If set to 1 all events that belong to this node (and the ticket''''s company) and not explicitly added to a ticket (tt.event_interface.addevent())
          but with tt.event_interface.newevent() will be dropped. This causes no escalation actions or notifications to be processed for
          those events during the service window period. Of course the upcoming event must provide a host (service id), otherwise it is not possible
          to determine, if there is a service window. This function is implemented in tt.event_interface.newevent().';
COMMENT ON COLUMN tt.maintenance_window.disable_guma_escalation IS E'If set to 1 any escalation to mcc, the customer and the isp caused by GUMA events is turned off during the service
          window. Only for these GUMA events escalation is suppressed: id alert, hardware error, application failure, system failure.
          If an escalation is to be suppressed is determined in event_interface.exec_event_type_actions() by calling the function tt.event_interface.is_esc_supp_active().
          The following conditions must be met for an escalation to be suppressed:
          (1) for the host (service_id the event belongs to a currently open service window must exist, which has the disable_conn_escalation flag set to 1
          (2) the tt.event_type.id must be one out of these 10002 (id alert), 10005 (hardware error), 10007 (application failure) or 10009 (system failure)
          When the escalation is to be suppressed, no action will be carried out by tt.event_interface.exec_event_type_actions().';
COMMENT ON COLUMN tt.maintenance_window.disable_notification IS E'If set to 1 notification for any added event to this ticket is turned off during the service window.
          However the notification ticket bound events (resolved, manual event added and waiting) and test notifications
          will not be affected.
          Implementation is in tt.osag_notify.is_notify_suppressor_active() which checks if there is a service window open for the ticket that has
          the disable_notification flag set to 1. If so the procedure notify.event_notify() leaves out any registered notifications for this event tpye.
          It does handle the ticket specific notifications anyway.';
