	latitude_direction varchar(1),
	longitude_degrees smallint,
	longitude_minutes smallint,
	longitude_seconds numeric,
	longitude_direction varchar(1),
	postal_code varchar(32),
	identifier varchar(32),
	company_id bigint NOT NULL,
	city_id bigint NOT NULL,
	local_company_name varchar(1024),
	proforma_comments varchar(1024),
	physical_access_comments varchar(2000),
	comments varchar(2000),
	cust_site_code varchar(10)
) ;
COMMENT ON TABLE mss.address IS E'Addresses (for coordinates see also http://www.tbs-sct.gc.ca/rpm-gbi/guides/Latlong_e.asp)';
COMMENT ON COLUMN mss.address.address_lines IS E'The address itself, typically street and number. Postal code,
city and country are stored in seperate fields.';
COMMENT ON COLUMN mss.address.address_shipping_lines IS E'Used if a location wants to get sent its equipment to another location. E.g. a central
IT management location. Postal code, city and country need to be stored in this field too.';
COMMENT ON COLUMN mss.address.cust_site_code IS E'Custom short identifier of a site';
COMMENT ON COLUMN mss.address.latitude_degrees IS E'Range: 0 to 90';
COMMENT ON COLUMN mss.address.latitude_direction IS E'Available values are: N (North) and S (South)';
COMMENT ON COLUMN mss.address.latitude_minutes IS E'Range: 0 to 59';
COMMENT ON COLUMN mss.address.latitude_seconds IS E'Range: 0 to 59 with optional decimals separated with a "."';
COMMENT ON COLUMN mss.address.local_company_name IS E'This needs to be set if the subcompany at this addres has a different name than the belonging mother
company, e.g. a holding.';
COMMENT ON COLUMN mss.address.longitude_degrees IS E'Range: 0 to 180';
COMMENT ON COLUMN mss.address.longitude_direction IS E'Available values are: E (East) or W (West) (O in some notations but we map it to W)';
COMMENT ON COLUMN mss.address.longitude_minutes IS E'Range 0 to 59';
COMMENT ON COLUMN mss.address.longitude_seconds IS E'Range: 0 to 59 with optional decimals separated with a "."';
