	synctunnelgroupsenabled smallint NOT NULL DEFAULT 1,
	nomcauthentication smallint NOT NULL DEFAULT 0,
	smsauthenabled smallint NOT NULL DEFAULT 0,
	mcdisplay smallint NOT NULL DEFAULT 1,
	aliasesenabled smallint NOT NULL DEFAULT 0,
	passwordexpiryenabled smallint NOT NULL DEFAULT 0,
	passwordexpiryoffset bigint,
	passwordonlyallowed smallint NOT NULL DEFAULT 1,
	tokensmanagedexternally smallint NOT NULL DEFAULT 0,
	autoemailaliasesenabled smallint NOT NULL DEFAULT 0,
	syncuserunitsenabled smallint NOT NULL DEFAULT 0,
	syncuseraccountcontrolenabled smallint NOT NULL DEFAULT 0,
	automaticpasswordresetenabled smallint NOT NULL DEFAULT 1,
	allow_weak_passwords smallint NOT NULL DEFAULT 0,
	description varchar(2000),
	softtokenenabled smallint NOT NULL DEFAULT 0,
	custom_soft_token_label varchar(50),
	tmppwdonlyexpiryoffset bigint NOT NULL DEFAULT 259200,
	useractivationmailsenabled smallint NOT NULL DEFAULT 0,
	allowsofttokenreuse smallint NOT NULL DEFAULT 0,
	maxretries smallint NOT NULL DEFAULT 10,
	notify_contact_changes smallint NOT NULL DEFAULT 0
) ;
COMMENT ON COLUMN auth.authsys.aliasesenabled IS E'Aliases can be edited in mc users management.';
COMMENT ON COLUMN auth.authsys.allow_weak_passwords IS E'If true, no password strength checks are done.';
COMMENT ON COLUMN auth.authsys.allowsofttokenreuse IS E'If true, resending the Software Token activation QR code is allowed.';
COMMENT ON COLUMN auth.authsys.autoemailaliasesenabled IS E'email address are automatically listed as alias if this is switched on. (only applies to synchronized users
(currently...))';
COMMENT ON COLUMN auth.authsys.automaticpasswordresetenabled IS E'Whether passwords can be resetted via the automated link-mail process MC-2431';
COMMENT ON COLUMN auth.authsys.custom_soft_token_label IS E'If not null this label will be used in the QR code for the soft token activation.';
COMMENT ON COLUMN auth.authsys.maxretries IS E'Specifies the max password retry attempts one has before the account becomes locked. This value is transferred to AUTH.LOGIN.MAXRETRIES';
COMMENT ON COLUMN auth.authsys.mcdisplay IS E'This authsys is visible in mission control users management.';
COMMENT ON COLUMN auth.authsys.notify_contact_changes IS E'Sends out a notification email and SMS on any account change';
COMMENT ON COLUMN auth.authsys.passwordexpiryenabled IS E'the password expiry setting can be edited in mc users management';
COMMENT ON COLUMN auth.authsys.passwordexpiryoffset IS E'Specifies the offset from now, in seconds, that is used to calculate the default
(or next) value for the login.passwordexpiry field (e.g. when creating a new login)
a 0 or negative value means that the password expires immediately
a NULL value means that password expiry is defaulted to off
both (< 0 and NULL) prevent an automatic update of the
expiration end upon password change by the user';
COMMENT ON COLUMN auth.authsys.passwordonlyallowed IS E'it is allowed to have password only authentication type';
COMMENT ON COLUMN auth.authsys.smsauthenabled IS E'Whether SMS authentication is available on this authsystem.';
COMMENT ON COLUMN auth.authsys.syncuseraccountcontrolenabled IS E'Whether synchronizing the "locked" flag is enabled.';
COMMENT ON COLUMN auth.authsys.syncuserunitsenabled IS E'Enable/Disable user unit synchronization over AD sync';
COMMENT ON COLUMN auth.authsys.tmppwdonlyexpiryoffset IS E'value in seconds which is added to the current date to set the users AUTH.LOGIN.TMPPWDONLYEXPIRY field when ticking the checkbox.';
COMMENT ON COLUMN auth.authsys.tokensmanagedexternally IS E'token issuing and replacement is not managed via MC UI';
CREATE INDEX idx_authsys_company ON auth.authsys (company_id);
ALTER TABLE auth.authsys ADD PRIMARY KEY (id);

