CREATE TABLE mss.field_mapping (
	id bigint NOT NULL,
	object_type_id bigint NOT NULL,
	java_field_name varchar(128) NOT NULL,
	field_mapping_type_id bigint NOT NULL,
	column_name varchar(32),
	ref_table varchar(65),
	ref_column varchar(32),
	element_column varchar(32),
	link_table varchar(65)
) ;
COMMENT ON TABLE mss.field_mapping IS E'stores java/sql field mapping information (filled by the mapping2table script. IDs are NOT guaranteed to stay the same for a given field name.
these objects/rows are not to be referenced by others.)';
COMMENT ON COLUMN mss.field_mapping.column_name IS E'the database column name in case of simple values or one-to-one mappings (for one-one, the column contains an ID)';
COMMENT ON COLUMN mss.field_mapping.element_column IS E'the "forward-reference" column name in many-many link tables, the column which points to the element table';
COMMENT ON COLUMN mss.field_mapping.field_mapping_type_id IS E'mapping type (value, one-many, etc.)';
COMMENT ON COLUMN mss.field_mapping.java_field_name IS E'the java field name';
COMMENT ON COLUMN mss.field_mapping.link_table IS E'the link-table for many-many mappings';
COMMENT ON COLUMN mss.field_mapping.object_type_id IS E'the object type where this field belongs to';
COMMENT ON COLUMN mss.field_mapping.ref_column IS E'the "back-reference" column name in REF_TABLE for one-many and many-many mappings';
COMMENT ON COLUMN mss.field_mapping.ref_table IS E'the referenced table in case of one-one, one-many and many-many mappings (for many-many, this ist not the link-table, but the table where the link table points to)';
ALTER TABLE mss.field_mapping ADD PRIMARY KEY (id);

ALTER TABLE mss.field_mapping ADD CONSTRAINT field_mapping_fk1 FOREIGN KEY (OBJECT_TYPE_ID) REFERENCES MSS.OBJECT_TYPE (ID);

ALTER TABLE mss.field_mapping ADD CONSTRAINT field_mapping_fk2 FOREIGN KEY (FIELD_MAPPING_TYPE_ID) REFERENCES MSS.FIELD_MAPPING_TYPE (ID);


