CREATE TABLE prx.url_miscategorization (
	id bigint NOT NULL,
	company_id bigint NOT NULL,
	ref_id varchar(100) NOT NULL,
	url varchar(4000) NOT NULL,
	url_miscat_status_id bigint NOT NULL,
	comments varchar(2000),
	reason varchar(2000),
	creation_date timestamp NOT NULL DEFAULT statement_timestamp(),
	last_checked_date timestamp,
	completion_date timestamp
) ;
COMMENT ON TABLE prx.url_miscategorization IS E'Meta information of miscategorization report send to Cyren.';
COMMENT ON COLUMN prx.url_miscategorization.comments IS E'The comments written in the recategorization request (provided by user/MC).';
COMMENT ON COLUMN prx.url_miscategorization.company_id IS E'The company ID this recategorization request belongs to.';
COMMENT ON COLUMN prx.url_miscategorization.completion_date IS E'Date of status change from IN PROGRESS => CHANGED/NOT CHANGED.';
COMMENT ON COLUMN prx.url_miscategorization.creation_date IS E'Date of recategorization creation.';
COMMENT ON COLUMN prx.url_miscategorization.last_checked_date IS E'Date of last check of this request.';
COMMENT ON COLUMN prx.url_miscategorization.reason IS E'The reject reason provided by Cyren on declined recategorization.';
COMMENT ON COLUMN prx.url_miscategorization.ref_id IS E'The Cyren recategorization ID.';
COMMENT ON COLUMN prx.url_miscategorization.url IS E'The reported URL.';
COMMENT ON COLUMN prx.url_miscategorization.url_miscat_status_id IS E'The Status of the miscategorization request, e.g. IN PROGRESS, CHANGED, NOT CHANGED.';
CREATE INDEX idx_url_miscat_company ON prx.url_miscategorization (company_id);
