CREATE TABLE tt.event_notification_0512 (
	id numeric(22) NOT NULL,
	login_id numeric(22) NOT NULL,
	event_notification_type_id numeric(22) NOT NULL,
	comments varchar(1024),
	event_type_id numeric(22),
	event_type_group_id numeric(22),
	company_id numeric(22),
	service_id numeric(22),
	company_unit_id numeric(22),
	service_type_id numeric(22),
	ticket_id numeric(22),
	ticket_type_id numeric(22),
	regexp varchar(512),
	only_if_worker smallint NOT NULL DEFAULT 0
) ;
COMMENT ON COLUMN tt.event_notification_0512.company_id IS E'Matches Company';
COMMENT ON COLUMN tt.event_notification_0512.company_unit_id IS E'Matches Company Unit';
COMMENT ON COLUMN tt.event_notification_0512.event_notification_type_id IS E'Type of notification (e.g. SMS, email)';
COMMENT ON COLUMN tt.event_notification_0512.event_type_group_id IS E'Matches group of events (e.g. VPN-related events)';
COMMENT ON COLUMN tt.event_notification_0512.event_type_id IS E'Matches kind of event (e.g. ISP outage)';
COMMENT ON COLUMN tt.event_notification_0512.id IS E'Notification ID';
COMMENT ON COLUMN tt.event_notification_0512.login_id IS E'Login / Contact that is notified';
COMMENT ON COLUMN tt.event_notification_0512.only_if_worker IS E'If this is non-0, the notification is only sent if the notification owner is the
assigned worker of the associated ticket. Obviously, this is an OSAG-only feature.';
COMMENT ON COLUMN tt.event_notification_0512.regexp IS E'Matches regular expression on event public content';
COMMENT ON COLUMN tt.event_notification_0512.service_id IS E'Matches MSS Service (e.g. cust-prx-1, cust-prx-2)';
COMMENT ON COLUMN tt.event_notification_0512.service_type_id IS E'Matches Service Type (e.g. Security Gateway)';
COMMENT ON COLUMN tt.event_notification_0512.ticket_id IS E'Matches a specific Ticket';
COMMENT ON COLUMN tt.event_notification_0512.ticket_type_id IS E'Matches Ticket Type (e.g. trouble ticket)';


